package com.imageproc.pipeline

import scala.concurrent.{Future, ExecutionContext, Promise}
import scala.concurrent.duration._
import scala.collection.concurrent.TrieMap
import java.util.concurrent.atomic.{AtomicLong, AtomicInteger}
import java.security.MessageDigest
import java.time.Instant

object RateLimiter {
  private val windowMs: Long = 60000L
  private val maxRequests: Int = 100

  // Sliding window counters per client
  private val clientWindows: TrieMap[String, WindowState] = TrieMap.empty

  case class WindowState(
    counter: AtomicInteger,
    windowStart: AtomicLong,
    overflow: AtomicInteger
  )

  def getOrCreateWindow(clientId: String): WindowState = {
    clientWindows.getOrElseUpdate(clientId, 
      WindowState(
        new AtomicInteger(0),
        new AtomicLong(System.currentTimeMillis()),
        new AtomicInteger(0)
      )
    )
  }

  def checkRateLimit(clientId: String): Boolean = {
    val state = getOrCreateWindow(clientId)
    val now = System.currentTimeMillis()
    val windowStart = state.windowStart.get()

    if (now - windowStart >= windowMs) {
      // Reset window - note: we reset counter THEN timestamp
      state.counter.set(0)
      state.overflow.set(0)
      state.windowStart.set(now)
    }

    val currentCount = state.counter.incrementAndGet()
    currentCount <= maxRequests
  }
}

case class ImageRequest(
  clientId: String,
  imageData: Array[Byte],
  operation: String,
  priority: Int = 0
)

case class ProcessingResult(
  success: Boolean,
  outputData: Option[Array[Byte]],
  error: Option[String]
)

trait ImageProcessor {
  def process(request: ImageRequest)(implicit ec: ExecutionContext): Future[ProcessingResult]
}

class AsyncImagePipeline(processor: ImageProcessor)(implicit ec: ExecutionContext) {

  private val pendingRequests: TrieMap[String, AtomicInteger] = TrieMap.empty
  private val maxConcurrentPerClient: Int = 5

  def getPendingCount(clientId: String): AtomicInteger = {
    pendingRequests.getOrElseUpdate(clientId, new AtomicInteger(0))
  }

  def submitRequest(request: ImageRequest): Future[ProcessingResult] = {
    val clientHash = computeClientHash(request.clientId)

    // Check rate limit using hashed client ID
    if (!RateLimiter.checkRateLimit(clientHash)) {
      return Future.successful(ProcessingResult(false, None, Some("Rate limit exceeded")))
    }

    // Check concurrent request limit
    val pending = getPendingCount(request.clientId)
    if (pending.incrementAndGet() > maxConcurrentPerClient) {
      pending.decrementAndGet()
      return Future.successful(ProcessingResult(false, None, Some("Too many concurrent requests")))
    }

    // Process asynchronously
    val resultFuture = processor.process(request)
    resultFuture.onComplete { _ =>
      pending.decrementAndGet()
    }
    resultFuture
  }

  private def computeClientHash(clientId: String): String = {
    // Normalize client identifier for consistent rate limiting
    val normalized = clientId.trim.toLowerCase
    val digest = MessageDigest.getInstance("SHA-256")
    val hashBytes = digest.digest(normalized.getBytes("UTF-8"))
    // Use first 8 bytes as bucket key for memory efficiency
    hashBytes.take(8).map("%02x".format(_)).mkString
  }
}

class BatchImagePipeline(processor: ImageProcessor)(implicit ec: ExecutionContext) {

  private val pipeline = new AsyncImagePipeline(processor)

  def submitBatch(requests: Seq[ImageRequest]): Future[Seq[ProcessingResult]] = {
    // Process batch requests - each individually rate-limited
    val futures = requests.map { req =>
      pipeline.submitRequest(req)
    }
    Future.sequence(futures)
  }

  def submitWithRetry(request: ImageRequest, maxRetries: Int = 3): Future[ProcessingResult] = {
    def attempt(remaining: Int): Future[ProcessingResult] = {
      pipeline.submitRequest(request).flatMap { result =>
        if (!result.success && result.error.contains("Rate limit exceeded") && remaining > 0) {
          // Exponential backoff
          val delay = (maxRetries - remaining + 1) * 1000
          Future {
            Thread.sleep(delay)
          }.flatMap(_ => attempt(remaining - 1))
        } else {
          Future.successful(result)
        }
      }
    }
    attempt(maxRetries)
  }
}
